window.docContents[50].resolve({"/rules/PL1006/#PL1006-proof-shape":{"contents":"A total replacement keeps the same domain and result type; if it changes behavior, state and prove the relation to the intended function.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1006: Unsafe and partial declarations require exact helper authentication","header":"Required proof shape","id":"/rules/PL1006/#PL1006-proof-shape"},"/rules/PL2005/#PL2005-proof-shape":{"contents":"The replayed declaration must type-check in the kernel with exactly its stated type and value.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2005: Required admission and source evidence must be complete","header":"Required proof shape","id":"/rules/PL2005/#PL2005-proof-shape"},"/rules/PL4003/#PL4003-proof-shape":{"contents":"No proof obligation: the example demonstrates a rejection. Its pattern is part of the claim and is reviewed with the prose.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4003: Negative examples require completed intended rejection","header":"Required proof shape","id":"/rules/PL4003/#PL4003-proof-shape"},"/rules/PL5002/#PL5002-proof-shape":{"contents":"No proof obligation: the rule checks presence. The docstring must describe the elaborated statement faithfully.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5002: Registered public material declarations require docstrings","header":"Required proof shape","id":"/rules/PL5002/#PL5002-proof-shape"}});